#!/usr/bin/env python3
"""Build the semantic-verifier training set: (concept anchor, item text) -> faithful or not.

Positives are item/anchor pairs whose item is verified by construction:
  * gold bank seeds paired with a concept of their own unit (`bank.facts[key][unit]`),
  * items generated by the parametric engine, paired with the law they were computed from,
  * items projected from the closed-world fact tables, paired with their row's definition.
Negatives are the *hard* ones:
  * rejection-sampling candidates of the 10M model that passed the lexical gate (the junk we want to reject),
  * the same candidates paired with an anchor from another subject (teaches on-topic-ness),
  * gold MCQs whose key has been swapped with a distractor (teaches key support),
  * param/fact items paired with an unrelated anchor.

usage: python3 eval/build_verifier_data.py --bank docs/model/bank.json --out /tmp/paperlm/vf [--rft DIR] [--n 30000]
"""
import argparse
import glob
import json
import os
import random
import sys

HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.dirname(HERE)
sys.path[:0] = [os.path.join(ROOT, "engine"), HERE]
import parametric as PM  # noqa: E402
import factbank as FB  # noqa: E402


def item_text(it):
    parts = [it.get("question") or "", *(it.get("options") or [])]
    parts += [p.get("text", "") for p in (it.get("parts") or [])]
    parts += [p.get("text", "") for p in (it.get("or_parts") or [])]
    parts += [it.get("explanation") or "", it.get("rubric") or ""]
    return " ".join(x for x in parts if x)


def main():
    ap = argparse.ArgumentParser(); ap.add_argument("--bank", default=os.path.join(ROOT, "docs", "model", "bank.json"))
    ap.add_argument("--out", default="/tmp/paperlm/vf"); ap.add_argument("--rft", default="/tmp/paperlm/rft")
    ap.add_argument("--n", type=int, default=30000); ap.add_argument("--seed", type=int, default=7)
    a = ap.parse_args()
    rng = random.Random(a.seed)
    bank = json.load(open(a.bank, encoding="utf-8"))
    fb = FB.FactBank()
    pos, neg = [], []

    # ---- positives: gold bank seeds + a concept of their own unit
    allpos = []
    for key, units in bank.get("seeds", {}).items():
        facts = bank.get("facts", {}).get(key, {})
        for unit, seeds in units.items():
            fs = facts.get(unit) or [x for v in facts.values() for x in v]
            if not fs:
                continue
            for s in seeds:
                c = s.get("c")
                if c == "mcq":
                    if not s.get("o") or s.get("k") not in "abcd" or not s.get("w"):
                        continue
                    txt = s["q"] + " " + " ".join(s["o"]) + " " + s["w"]
                else:
                    if not s.get("q") or not s.get("r"):
                        continue
                    txt = s["q"] + " " + " ".join(t[1] for t in s.get("p") or []) + " " + s["r"]
                allpos.append(dict(anchor=rng.choice(fs), text=txt[:900], label=1, kind="bank", ref=f"{key}|{unit}"))
    rng.shuffle(allpos)
    pos += allpos

    # ---- positives: parametric + fact tier
    subjects = [("physics", "C12", "Kinematics"), ("physics", "C12", "Current electricity"), ("physics", "C11", "Heat and Temperature"),
                ("chemistry", "C12", "Chemical equilibrium"), ("chemistry", "C12", "Electrochemistry"), ("mathematics", "C12", "Derivatives"),
                ("mathematics", "C11", "Probability"), ("botany", "CEE", "Photosynthesis and Respiration"), ("zoology", "CEE", "Circulatory System"),
                ("fundamentals-of-nursing", "BSN", "General"), ("science", "C10", "Pressure"), ("civil-engineering-materials", "BE", "Concrete")]
    for _ in range(a.n // 6):
        subj, lvl, unit = rng.choice(subjects)
        if rng.random() < 0.5:
            it = PM.make_item(subj, lvl, unit, rng.choice([1, 4]), rng.choice(["MCQ", "SHORT", "NUMERICAL"]), rng)
            if not it:
                continue
            pos.append(dict(anchor=it["concept"], text=item_text(it)[:900], label=1, kind="param", ref=it.get("tpl")))
        else:
            it = fb.make_item(subj, unit, rng.choice([1, 5]), rng.choice(["MCQ", "SHORT"]), rng.random)
            if not it:
                continue
            cls = next(c for c in fb.classes if c["id"] == it["fact_id"])
            pos.append(dict(anchor=cls["pairs"][it["fact_row"]][2], text=item_text(it)[:900], label=1, kind="fact", ref=cls["id"]))
    rng.shuffle(pos)
    pos = pos[:a.n]

    # ---- negatives: RFT candidates (hard) + mismatches + key swaps
    cands = []
    for p in glob.glob(os.path.join(a.rft, "*", "cand_*.jsonl")):
        for line in open(p, encoding="utf-8"):
            try:
                r = json.loads(line)
            except Exception:
                continue
            anc = r.get("anchor") or ""
            txt = r.get("text", "").split("<|q|>", 1)[-1]
            if anc and txt:
                cands.append((anc, txt))
    rng.shuffle(cands)
    print("rft hard negatives:", len(cands), "positives:", len(pos), flush=True)
    for anc, txt in cands[:a.n // 2]:
        neg.append(dict(anchor=anc, text=txt[:900], label=0, kind="lm_gate_pass"))
    pool = [p["anchor"] for p in pos]
    for p in pos[:a.n // 2]:
        neg.append(dict(anchor=rng.choice(pool), text=p["text"][:900], label=0, kind="anchor_mismatch"))
    for p in allpos:
        if p["text"] and rng.random() < 0.15:
            neg.append(dict(anchor=p["anchor"], text=p["text"][:900], label=0, kind="corrupted"))
    rng.shuffle(neg)

    # ---- split
    rng.shuffle(pos); rng.shuffle(neg)
    n_val = max(500, int(0.08 * (len(pos) + len(neg))))
    val = pos[:n_val // 2] + neg[:n_val // 2]
    tr = pos[n_val // 2:] + neg[n_val // 2:]
    rng.shuffle(tr); rng.shuffle(val)
    os.makedirs(a.out, exist_ok=True)
    for name, rows in (("train", tr), ("val", val)):
        with open(os.path.join(a.out, f"{name}.jsonl"), "w", encoding="utf-8") as f:
            for r in rows:
                f.write(json.dumps(r) + "\n")
    stats = dict(positive=len(pos), negative=len(neg), train=len(tr), val=len(val),
                 kinds={k: sum(1 for r in pos + neg if r["kind"] == k) for k in sorted({r["kind"] for r in pos + neg})})
    json.dump(stats, open(os.path.join(a.out, "stats.json"), "w"), indent=1)
    print(json.dumps(stats, indent=1))


if __name__ == "__main__":
    main()
